#include <cstdio>

using int64 = long long;

constexpr int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exponent) {
    int64 result = 1;
    while (exponent > 0) {
        if (exponent & 1)
            result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    int64 n;
    std::scanf("%lld", &n);

    int64 value = modPow(2, n);
    std::printf("%lld", value * ((value + 1) % MOD) % MOD * 500000004 % MOD);

    return 0;
}

